import re

# 1. Safely extract memos from the previous node
memos_iniciales = []
for item in _('Get many rows3').all():
    # Adding a safe .get() in case the previous node outputs empty items
    data = item.to_py().get("json", {})
    text = data.get("analysis_data", "")

    # Extract text before the colon safely
    match = re.search(r'^[^:]+', text)
    if match:
        memos_iniciales.append(text)

# 2. Build a mapping dictionary to prevent overwriting documents
results_map = {m: {} for m in memos_iniciales}

# 3. Process the current input exactly once
for item in _input.all():
    data = item.to_py().get("json", {})
    doc_name = data.get("doc_name")
    tests_per_doc = data.get("metadata", {}).get("insight_evaluations", [])

    # Iterate through evaluations and match them by index to the memos
    for nn, test in enumerate(tests_per_doc):
        if nn < len(memos_iniciales):
            memo_name = memos_iniciales[nn]
            conf_status = test.get("hypothesis_confirmation_status")
            verdict = test.get("verdict_rationale")

            # Store the status for this specific document
            if doc_name and conf_status:
                results_map[memo_name][doc_name] = conf_status +  " [" + verdict + "]"

# 4. Format into a clean list of dicts AND calculate the summary counts
final_output = []
for memo_name, doc_evaluations in results_map.items():

    # Initialize our counters for this specific memo
    counts = {
        "Confirmed by contrast": 0,
        "Positively Confirmed": 0,
        "Not Confirmed": 0
    }

    # Tally up the statuses across all documents for this memo
    for status in doc_evaluations.values():
      for i in counts.keys(): 
        if i in status[0:25]:
            counts[i] += 1

    # Append the memo, the raw document mapping, and the aggregated counts
    final_output.append({
        "memo": memo_name,
        "document_statuses": doc_evaluations,

        "counts": {
          "Positively Confirmed": counts["Positively Confirmed"],
          "Confirmed by Contrast": counts["Confirmed by contrast"],
          "Not Confirmed": counts["Not Confirmed"]
        }
    })

return final_output

